// Reproducible preview build.
//
// 1. Regenerates public/js/worker-source.mjs from the fixed core source
//    (public/js/core/semver.mjs, embedded verbatim) plus a fixed
//    onmessage handler, so the page can create a module Worker from a
//    Blob URL without any fetch. The generated file is committed; check
//    verifies it matches what this script would produce.
// 2. Copies public/ verbatim into dist-preview/, adds a deny-all
//    robots.txt, and writes BUILD-MANIFEST.json (path, bytes, sha256 per
//    file, sorted). No timestamps or environment data enter the output,
//    so running the build twice produces byte-identical results.
// Production mode is refused: no production origin has been approved
// for this tool.
//
// check.mjs imports buildWorkerSource from this module; the CLI entry
// point runs only when the file is executed directly.

import { createHash } from "node:crypto";
import { copyFile, lstat, mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, extname, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const PROJECT_ROOT = resolve(fileURLToPath(new URL("..", import.meta.url)));
const PUBLIC_ROOT = resolve(PROJECT_ROOT, "public");
const DIST_ROOT = resolve(PROJECT_ROOT, "dist-preview");
const MANIFEST_PATH = resolve(PROJECT_ROOT, "BUILD-MANIFEST.json");
const CORE_PATH = resolve(PUBLIC_ROOT, "js/core/semver.mjs");
const WORKER_SOURCE_PATH = resolve(PUBLIC_ROOT, "js/worker-source.mjs");
const ALLOWED_EXTENSIONS = new Set([".html", ".css", ".js", ".mjs"]);

// Fixed message handler appended to the embedded core source. It is the
// only code that runs inside the worker besides the core itself.
export const WORKER_HANDLER = `self.onmessage = (event) => {
  const data = event && event.data ? event.data : null;
  if (data === null || typeof data.generation !== "number" || !data.input) return;
  let outcome;
  try {
    outcome = run(data.input);
  } catch {
    outcome = { ok: false, error: { code: "INTERNAL", field: null, row: null } };
  }
  self.postMessage({ generation: data.generation, outcome });
};
`;

export function buildWorkerSource(coreSource) {
  const workerSource = `${coreSource}\n${WORKER_HANDLER}`;
  const sha256 = createHash("sha256").update(workerSource, "utf8").digest("hex");
  const file = `// GENERATED by scripts/build.mjs — do not edit by hand.
// Source: public/js/core/semver.mjs (embedded verbatim) + a fixed onmessage
// handler. The page creates a module Worker from this string via a Blob URL.
export const WORKER_SOURCE = ${JSON.stringify(workerSource)};
export const WORKER_SOURCE_SHA256 = ${JSON.stringify(sha256)};
`;
  return { file, sha256 };
}

async function collectFiles(directory, base = directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const files = [];
  for (const entry of entries) {
    const fullPath = resolve(directory, entry.name);
    const info = await lstat(fullPath);
    if (info.isSymbolicLink()) {
      throw new Error(`Symbolic links are not allowed in build sources: ${fullPath}`);
    }
    if (entry.name.startsWith(".")) {
      throw new Error(`Dotfiles are not allowed in build sources: ${fullPath}`);
    }
    if (info.isDirectory()) {
      files.push(...(await collectFiles(fullPath, base)));
      continue;
    }
    if (!info.isFile() || !ALLOWED_EXTENSIONS.has(extname(entry.name).toLowerCase())) {
      throw new Error(`Unsupported file type in build sources: ${fullPath}`);
    }
    files.push(relative(base, fullPath).split(sep).join("/"));
  }
  return files;
}

async function runBuild() {
  const modeArg = process.argv.find((arg) => arg.startsWith("--mode"));
  const mode = modeArg
    ? process.argv[process.argv.indexOf(modeArg) + 1] ?? modeArg.split("=")[1]
    : undefined;
  if (mode !== "preview") {
    throw new Error(
      mode === "production"
        ? "Production origin not approved; no production build."
        : "Explicit --mode preview is required.",
    );
  }

  // Step 1: regenerate the embedded worker source.
  const coreSource = await readFile(CORE_PATH, "utf8");
  const { file: workerSourceFile } = buildWorkerSource(coreSource);
  await writeFile(WORKER_SOURCE_PATH, workerSourceFile, "utf8");

  // Step 2: copy public/ into dist-preview/.
  const files = await collectFiles(PUBLIC_ROOT);
  await rm(DIST_ROOT, { recursive: true, force: true });
  await mkdir(DIST_ROOT, { recursive: true });
  for (const path of files) {
    const destination = resolve(DIST_ROOT, path);
    await mkdir(dirname(destination), { recursive: true });
    await copyFile(resolve(PUBLIC_ROOT, path), destination);
  }
  await writeFile(resolve(DIST_ROOT, "robots.txt"), "User-agent: *\nDisallow: /\n", "utf8");

  const manifestFiles = [];
  for (const path of [...files, "robots.txt"].sort()) {
    const bytes = await readFile(resolve(DIST_ROOT, path));
    manifestFiles.push({
      path,
      bytes: bytes.length,
      sha256: createHash("sha256").update(bytes).digest("hex"),
    });
  }
  const manifest = { mode, files: manifestFiles };
  await writeFile(MANIFEST_PATH, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");

  console.log(
    `Preview build: ${manifestFiles.length} files written to dist-preview/ with BUILD-MANIFEST.json`,
  );
}

const isMain =
  process.argv[1] !== undefined &&
  import.meta.url === new URL(`file://${process.argv[1]}`).href;
if (isMain) {
  await runBuild();
}
